//! Variable fonts at their default instance, their named instances and
//! other coordinates: two small fonts generated by
//! `tests/fixtures/gen_variable_fonts.py`, one with TrueType outlines
//! (`gvar`, `HVAR`, `MVAR`, `avar`) and one with CFF2 outlines, against
//! FreeType 2.14.3's view of them.

mod common;

use common::fixture_path;
use common::json::{Fixture, Json};
use pltrs_font::{
    AutohintTarget, Autohinter, Face, GlyphId, ScanOutline, ScanPointKind, Size, Tag,
};

/// FreeType's tag of a point (`FT_CURVE_TAG`): 1 on, 0 conic, 2 cubic.
fn tag(kind: ScanPointKind) -> i64 {
    match kind {
        ScanPointKind::On => 1,
        ScanPointKind::Conic => 0,
        ScanPointKind::Cubic => 2,
    }
}

/// The points of `outline` as FreeType records them: `[x, y, tag]` and the
/// contour end indices.
fn points(outline: &ScanOutline) -> (Vec<Vec<i64>>, Vec<i64>) {
    let points = outline
        .points
        .iter()
        .map(|point| vec![point.x, point.y, tag(point.kind)])
        .collect();
    let ends = outline
        .contour_ends
        .iter()
        .map(|&end| end as i64 - 1)
        .collect();
    (points, ends)
}

/// FreeType's points and contour ends of a recorded load.
fn expected_points(load: &Json) -> (Vec<Vec<i64>>, Vec<i64>) {
    let points = load
        .field("points")
        .array()
        .iter()
        .map(Fixture::i64s)
        .collect();
    (points, load.field("ends").i64s())
}

/// Puts `face` at the recorded instance `entry`.
fn set_instance(face: &mut Face<'_>, entry: &Json) {
    match entry.opt("instance") {
        None => {}
        Some(instance) => match instance.as_f64_vec() {
            Some(coords) => face
                .set_variations(&[
                    (Tag::new(b"wght"), coords[0]),
                    (Tag::new(b"wdth"), coords[1]),
                ])
                .expect("design coordinates"),
            None => face
                .set_named_instance(instance.i64() as usize - 1)
                .expect("named instance"),
        },
    }
}

fn check_font(file: &str, key: &str) {
    let expected = common::fixture("synthetic-var.json");
    let data = std::fs::read(fixture_path(file)).expect("fixture");
    for entry in expected.field(key).array() {
        let label = format!("{file} {}", entry.field("label").str());
        let mut face = Face::parse(&data, 0).expect("variable font");
        set_instance(&mut face, entry);
        let normalized: Vec<i64> = face
            .normalized_coordinates()
            .iter()
            .map(|&coord| (coord * 65536.0).round() as i64)
            .collect();
        assert_eq!(normalized, entry.field("normalized").i64s(), "{label}");
        let metrics = vec![
            i64::from(face.ascender()),
            i64::from(face.descender()),
            i64::from(face.height()),
        ];
        assert_eq!(metrics, entry.field("metrics").i64s(), "{label}: metrics");
        let size = Size::new(&face, 15.0, 96.0);
        let autohinter = Autohinter::new(&face);
        for glyph in entry.field("glyphs").array() {
            let id = GlyphId(glyph.field("gid").i64() as u16);
            let what = format!("{label} glyph {}", id.0);
            let unscaled = glyph.field("unscaled");
            let (advance, bbox) = face.unscaled_metrics(id).expect("glyph");
            assert_eq!(advance, unscaled.field("advance").i64(), "{what}: advance");
            let xs: Vec<i64> = unscaled
                .field("points")
                .array()
                .iter()
                .map(|p| p.i64s()[0])
                .collect();
            if let (Some(bbox), Some(&min)) = (bbox, xs.iter().min()) {
                assert_eq!(i64::from(bbox.x_min), min, "{what}: unscaled x_min");
            }
            let scaled = glyph.field("scaled");
            let outline = size.scan_outline(&face, id).expect("scaled");
            assert_eq!(points(&outline), expected_points(scaled), "{what}: scaled");
            assert_eq!(
                size.linear_advance(&face, id),
                scaled.field("linear").i64(),
                "{what}: linear advance"
            );
            let hinted = glyph.field("hinted");
            let loaded = if face.flavor() == pltrs_font::SfntFlavor::Cff {
                face.load_cff_hinted(&size, id)
            } else {
                autohinter.load_glyph(&face, &size, id, AutohintTarget::Normal)
            }
            .expect("hinted");
            assert_eq!(
                points(&loaded.scan_outline()),
                expected_points(hinted),
                "{what}: hinted"
            );
            assert_eq!(
                i64::from(loaded.advance()),
                hinted.field("advance").i64(),
                "{what}: hinted advance"
            );
        }
    }
}

#[test]
fn truetype_instances_match_freetype() {
    check_font("synthetic-var.ttf", "ttf");
}

#[test]
fn cff2_instances_match_freetype() {
    check_font("synthetic-var.otf", "otf");
}

#[test]
fn axes_and_instances_are_listed() {
    let data = std::fs::read(fixture_path("synthetic-var.ttf")).expect("fixture");
    let mut face = Face::parse(&data, 0).expect("variable font");
    let axes = face.variation_axes();
    let tags: Vec<Tag> = axes.iter().map(|axis| axis.tag).collect();
    assert_eq!(tags, [Tag::new(b"wght"), Tag::new(b"wdth")]);
    assert_eq!(
        (axes[0].minimum, axes[0].default, axes[0].maximum),
        (100.0, 400.0, 900.0)
    );
    assert_eq!(face.named_instances().len(), 3);
    assert!(face.set_named_instance(3).is_err());
    assert!(face.set_variations(&[(Tag::new(b"slnt"), 1.0)]).is_err());
    face.set_variations(&[(Tag::new(b"wght"), 900.0)]).unwrap();
    assert_eq!(face.normalized_coordinates(), [1.0, 0.0]);
    face.reset_variations();
    assert_eq!(face.normalized_coordinates(), [0.0, 0.0]);
    let plain_data = std::fs::read(fixture_path("synthetic-cff.otf")).unwrap();
    let plain = Face::parse(&plain_data, 0).unwrap();
    assert!(plain.variation_axes().is_empty() && plain.normalized_coordinates().is_empty());
}
